module special_number_counter (input clk, input rst_n, input start, input [1023:0] n_binary, input [9:0] k_in, output reg [31:0] result, output reg done); reg [2:0] state; reg [1023:0] valid_m; reg [31:0] count_result; reg [1023:0] n_reg; reg is_n_ge_1; reg [10:0] counter; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= 3'b000; valid_m <= 0; count_result <=0; n_reg <=0; is_n_ge_1 <=0; counter <=0; done <=0; end else begin case (state) 3'b000: if (start) state <= 3'b001; endcase 3'b001: state <= 3'b010; endcase 3'b010: if (counter < 5000) counter <= counter +1; else state <=3'b011; endcase 3'b011: ; endcase end end assign done = (state == 3'b011); endmodule